public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input strings must not be null");
    }

    // Convert both words to lowercase to ensure case-insensitivity
    word1 = word1.toLowerCase();
    word2 = word2.toLowerCase();

    // Create sets from the words to find common letters
    Set<Character> set1 = new HashSet<>();
    Set<Character> set2 = new HashSet<>();

    for (char c : word1.toCharArray()) {
        set1.add(c);
    }

    for (char c : word2.toCharArray()) {
        set2.add(c);
    }

    // Find the intersection of the two sets
    set1.retainAll(set2);

    // The number of common letters is the size of the intersection set
    int commonLetters = set1.size();

    // The sum of the lengths of the two words
    int totalLetters = word1.length() + word2.length();

    // If there are no common letters, the approximate value is 0
    if (commonLetters == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    // Find the greatest common divisor (GCD) of the numerator and denominator
    int gcd = gcd(commonLetters, totalLetters);

    // Reduce the fraction by dividing both the numerator and denominator by the GCD
    int numerator = commonLetters / gcd;
    int denominator = totalLetters / gcd;

    // Return the result as a string
    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

