public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;

    for (int num : nums) {
        sum += num;
    }

    if (n == 1) {
        return false;
    }

    boolean[][] dp = new boolean[n + 1][sum + 1];

    for (int i = 0; i <= n; i++) {
        dp[i][0] = true;
    }

    for (int i = 1; i <= n; i++) {
        for (int j = sum; j >= nums[i - 1]; j--) {
            dp[i][j] = dp[i - 1][j] || dp[i - 1][j - nums[i - 1]];
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        for (int j = 1; j <= sum; j++) {
            if (dp[i][j]) {
                if (i * (sum - j) == (n - i) * j) {
                    return true;
                }
            }
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Cost array cannot be null or empty");
    }

    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

