    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '(') {
            balance++;
        } else {
            balance--;

            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next character as it is already considered
