public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) {
            return result;
        }

        LinkedList<Integer> queue = new LinkedList<>();
        for (int i = 0; i <= 9; i++) {
            queue.add(i);
        }

        while (!queue.isEmpty()) {
            int num = queue.poll();
            if (num >= low && num <= high) {
                result.add(num);
            }
            if (num == 0 || num > high) {
                continue;
            }

            int lastDigit = num % 10;
            if (lastDigit > 0) {
                int nextNum = num * 10 + lastDigit - 1;
                if (nextNum <= high) {
                    queue.add(nextNum);
                }
            }
            if (lastDigit < 9) {
                int nextNum = num * 10 + lastDigit + 1;
                if (nextNum <= high) {
                    queue.add(nextNum);
                }
            }
        }

        result.sort(Integer::compare);
        return result;
    }

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    int count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long currentDigit = (n / factor) % 10;
        long lowerNumbers = n - (n / factor) * factor;
        long higherNumbers = n / (factor * 10);
        if (currentDigit == 0) {
            count += higherNumbers * factor;
        } else if (currentDigit == 1) {
            count += higherNumbers * factor + lowerNumbers + 1;
        } else {
            count += (higherNumbers + 1) * factor;
        }
    }
    return count;
}

