public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int longest = 0;

    int[][][] dp = new int[m][n][4]; // 0: horizontal, 1: vertical, 2: diagonal, 3: anti-diagonal

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0) ? dp[i][j - 1][0] + 1 : 1; // horizontal
                dp[i][j][1] = (i > 0) ? dp[i - 1][j][1] + 1 : 1; // vertical
                dp[i][j][2] = (i > 0 && j > 0) ? dp[i - 1][j - 1][2] + 1 : 1; // diagonal
                dp[i][j][3] = (i > 0 && j < n - 1) ? dp[i - 1][j + 1][3] + 1 : 1; // anti-diagonal

                longest = Math.max(longest, dp[i][j][0]);
                longest = Math.max(longest, dp[i][j][1]);
                longest = Math.max(longest, dp[i][j][2]);
                longest = Math.max(longest, dp[i][j][3]);
            }
        }
    }

    return longest;
}

