public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    Stack<Integer> stack = new Stack<>();

    for (int i = 0; i <= heights.length; i++) {
        int currentHeight = (i == heights.length) ? -1 : heights[i];

        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }

        stack.push(i);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Traverse upwards
            int r = Math.min(d, rows - 1);
            int c = d - r;
            while (r >= 0 && c < cols) {
                result[index++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            // Traverse downwards
            int c = Math.min(d, cols - 1);
            int r = d - c;
            while (r < rows && c >= 0) {
                result[index++] = mat[r][c];
                r++;
                c--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    // Convert the integer to a character array of its digits
    char[] digits = Integer.toString(n).toCharArray();

    // Iterate from the second last digit to the beginning
    for (int i = digits.length - 2; i >= 0; i--) {
        // If the current digit is less than the digit next to it
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit on the right side of (i) but greater than digits[i]
            int minIndex = i + 1;
            for (int j = i + 2; j < digits.length; j++) {
                if (digits[j] > digits[i] && digits[j] < digits[minIndex]) {
                    minIndex = j;
                }
            }
            // Swap the found digit with digits[i]
            char temp = digits[i];
            digits[i] = digits[minIndex];
            digits[minIndex] = temp;
            // Sort the digits after the current position to get the smallest number
            Arrays.sort(digits, i + 1, digits.length);
            // Convert the array back to an integer and return it
            return Integer.parseInt(new String(digits));
        }
    }
    // If no such digit is found, return -1
    return -1;
}

